import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const rows = JSON.parse(readFileSync(join(here, 'rows.json'), 'utf8'));

function invalidCursor(message) {
  const err = new Error(message);
  err.code = 'INVALID_CURSOR';
  return err;
}

function encodeCursor(offset) {
  return Buffer.from(JSON.stringify({ offset }), 'utf8').toString('base64url');
}

function decodeCursor(cursor) {
  if (typeof cursor !== 'string' || cursor.length === 0) {
    throw invalidCursor('cursor must be a non-empty string');
  }
  let obj;
  try {
    obj = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
  } catch {
    throw invalidCursor('cursor is not valid');
  }
  if (
    obj === null ||
    typeof obj !== 'object' ||
    Array.isArray(obj) ||
    typeof obj.offset !== 'number' ||
    !Number.isInteger(obj.offset) ||
    obj.offset < 0
  ) {
    throw invalidCursor('cursor is malformed');
  }
  return obj.offset;
}

function invalidParams(message) {
  const err = new Error(message);
  err.code = -32602;
  return err;
}

const tools = [
  {
    name: 'page',
    description: 'Page over rows.json. Returns a slice of rows and a next_cursor when more remain.',
    inputSchema: {
      type: 'object',
      properties: {
        limit: { type: 'integer', minimum: 1, maximum: 2, description: 'Number of rows to return (1 or 2).' },
        cursor: { type: 'string', description: 'Opaque cursor returned by a previous page call.' },
      },
      required: ['limit'],
      additionalProperties: false,
    },
  },
];

export async function listTools() {
  return tools;
}

export async function callTool(name, args = {}) {
  if (name !== 'page') {
    const err = new Error(`Unknown tool: ${name}`);
    err.code = -32601;
    throw err;
  }

  if (
    args === null ||
    typeof args !== 'object' ||
    Array.isArray(args)
  ) {
    throw invalidParams('arguments must be an object');
  }

  const allowed = new Set(Object.keys(tools[0].inputSchema.properties));
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw invalidParams(`unexpected argument: ${key}`);
    }
  }

  const { limit, cursor } = args;

  if (
    typeof limit !== 'number' ||
    !Number.isInteger(limit) ||
    limit < 1 ||
    limit > 2
  ) {
    throw invalidParams('limit must be an integer between 1 and 2');
  }

  let offset = 0;
  if (cursor !== undefined) {
    offset = decodeCursor(cursor);
  }

  // A cursor pointing past the end is stale and must not silently restart.
  if (offset > rows.length) {
    throw invalidCursor('cursor is stale');
  }

  const slice = rows.slice(offset, offset + limit);
  const nextOffset = offset + limit;
  const result = { rows: slice };
  if (nextOffset < rows.length) {
    result.next_cursor = encodeCursor(nextOffset);
  }
  return result;
}

